# Human prose spacing only; identifiers, dates, currency codes and source URLs stay exact.
human={'title','label','summary','identityBasis','status','dateBasis','period','response','falsifier','note','stage','locator','unit'}
def textclean(s):
 identifiers=re.findall(r'\b(?:OP[0-9]+|P[0-9]{6}|GoI)\b',s)
 for i,v in enumerate(identifiers):s=s.replace(v,'protectedidentifier'+chr(97+i),1)
 s=re.sub(r'([a-z])([A-Z])',r'\1 \2',s)
 s=re.sub(r'([A-Za-z])([0-9])',r'\1 \2',s)
 s=re.sub(r'([0-9])([A-Za-z])',r'\1 \2',s)
 s=re.sub(r'(?<=[;])(?=[A-Za-z0-9₹])',' ',s)
 s=re.sub(r'(?<=[a-z])(?=₹)',' ',s)
 for a,b in {'IFCinvestment':'IFC investment','IFCevent':'IFC event','Article IVsurveillance':'Article IV surveillance','loan84880':'loan84880'}.items():s=s.replace(a,b)
 for i,v in enumerate(identifiers):s=s.replace('protectedidentifier'+chr(97+i),v)
 return s
def clean(x,key=''):
 if isinstance(x,dict):return {k:clean(v,k) for k,v in x.items()}
 if isinstance(x,list):return [textclean(v) if isinstance(v,str) and key in ['limitations','alternativeExplanations'] else clean(v) for v in x]
 return textclean(x) if isinstance(x,str) and key in human else x
D=clean(D)
OUT.write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n')
print({k:len(v) for k,v in D.items()})
